-- Reviewed senior batch 006; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":2658,"word":"stringent","meaning":"嚴格的","example":"The laboratory has stringent rules for handling fragile equipment.","example_zh":"實驗室對操作精密易碎設備有嚴格規定。","original_meaning":"嚴格的","original_example":"Stringent regulations.","original_example_zh":"嚴格的法規。"},{"source_id":2659,"word":"subsidize","meaning":"補助","example":"The town will subsidize bus rides so more students can travel to school.","example_zh":"鎮公所將補助公車車資，讓更多學生方便上學。","original_meaning":"補助","original_example":"Subsidize farmers.","original_example_zh":"補貼農民。"},{"source_id":2660,"word":"suffice","meaning":"足夠","example":"One large watering can should suffice for these small flower beds.","example_zh":"一個大澆水壺應該足夠澆灌這些小花圃。","original_meaning":"足夠","original_example":"That will suffice.","original_example_zh":"這樣就夠了。"},{"source_id":2661,"word":"superficial","meaning":"膚淺的；表面的","example":"A superficial glance at the model failed to reveal the crack underneath.","example_zh":"只粗略看一下模型，沒能發現底下的裂縫。","original_meaning":"膚淺的","original_example":"A superficial wound.","original_example_zh":"表皮傷口。"},{"source_id":2662,"word":"suppress","meaning":"壓制","example":"Mei tried to suppress a laugh during the serious rehearsal.","example_zh":"嚴肅排練時，美努力忍住笑。","original_meaning":"壓制","original_example":"Suppress the rebellion.","original_example_zh":"鎮壓叛亂。"},{"source_id":2663,"word":"surge","meaning":"激增","example":"A surge of visitors arrived when the museum opened its new exhibition.","example_zh":"博物館新展覽開幕時，大批參觀者湧入。","original_meaning":"激增","original_example":"A surge in demand.","original_example_zh":"需求激增。"},{"source_id":2664,"word":"surplus","meaning":"過剩","example":"We donated the surplus vegetables from our school garden to a local shelter.","example_zh":"我們把校園菜園多收成的蔬菜捐給當地收容所。","original_meaning":"過剩","original_example":"A trade surplus.","original_example_zh":"貿易順差。"},{"source_id":2665,"word":"surveillance","meaning":"監視","example":"The museum uses surveillance cameras to help protect its valuable paintings.","example_zh":"博物館使用監視攝影機協助保護珍貴畫作。","original_meaning":"監視","original_example":"Under surveillance.","original_example_zh":"受到監控。"},{"source_id":2666,"word":"susceptible","meaning":"易受影響的","example":"Young seedlings are susceptible to damage from strong winds.","example_zh":"幼苗容易受到強風吹襲而受損。","original_meaning":"易受影響的","original_example":"Susceptible to disease.","original_example_zh":"易患疾病。"},{"source_id":2667,"word":"swift","meaning":"迅速的","example":"The lifeguard's swift response helped the tired swimmer reach the pool edge.","example_zh":"救生員迅速的反應，幫助疲憊泳客到達池邊。","original_meaning":"迅速的","original_example":"A swift response.","original_example_zh":"迅速的反應。"},{"source_id":2668,"word":"tangible","meaning":"有形的","example":"The finished birdhouse was tangible proof of the students' hard work.","example_zh":"完成的鳥屋是學生努力的具體成果。","original_meaning":"有形的","original_example":"Tangible results.","original_example_zh":"具體成果。"},{"source_id":2669,"word":"tariff","meaning":"關稅","example":"The tariff increased the cost of imported bicycles.","example_zh":"關稅提高了進口腳踏車的成本。","original_meaning":"關稅","original_example":"Import tariffs.","original_example_zh":"進口關稅。"},{"source_id":2670,"word":"tedious","meaning":"冗長的","example":"Sorting hundreds of tiny beads was tedious, but the team finished together.","example_zh":"分類數百顆小珠子很費工又乏味，但小組合作完成了。","original_meaning":"冗長的","original_example":"A tedious task.","original_example_zh":"一項繁瑣的任務。"},{"source_id":2671,"word":"terrain","meaning":"地形","example":"The rocky terrain made us walk slowly and carefully.","example_zh":"岩石遍布的地形讓我們走得緩慢又小心。","original_meaning":"地形","original_example":"Rugged terrain.","original_example_zh":"崎嶇的地形。"},{"source_id":2672,"word":"threshold","meaning":"門檻","example":"The puppy paused at the threshold before entering its new home.","example_zh":"小狗走進新家前，在門檻前停了一下。","original_meaning":"門檻","original_example":"Cross the threshold.","original_example_zh":"跨過門檻。"},{"source_id":2673,"word":"tolerate","meaning":"容忍","example":"These hardy plants can tolerate cold nights in the mountain garden.","example_zh":"這些耐寒植物能忍受山間花園寒冷的夜晚。","original_meaning":"容忍","original_example":"I cannot tolerate this.","original_example_zh":"我無法容忍這件事。"},{"source_id":2674,"word":"trajectory","meaning":"軌道；軌跡","example":"The students traced the trajectory of the ball as it curved through the air.","example_zh":"學生觀察球在空中拋出弧線的運動軌跡。","original_meaning":"軌道","original_example":"The trajectory of a missile.","original_example_zh":"飛彈的飛行軌跡。"},{"source_id":2675,"word":"traverse","meaning":"穿越","example":"The hikers will traverse the valley before reaching the campsite.","example_zh":"健行者將穿越山谷，再到達營地。","original_meaning":"穿越","original_example":"Traverse the desert.","original_example_zh":"穿越沙漠。"},{"source_id":2676,"word":"turbulent","meaning":"動盪的；湍急的","example":"The river became turbulent after days of heavy rain.","example_zh":"連日豪雨後，河水變得湍急。","original_meaning":"動盪的","original_example":"Turbulent times.","original_example_zh":"動盪的時期。"},{"source_id":2677,"word":"uncover","meaning":"揭露；發掘","example":"The students used soft brushes to uncover a buried clay pot.","example_zh":"學生用軟毛刷清理出埋在土裡的陶罐。","original_meaning":"揭露","original_example":"Uncover the truth.","original_example_zh":"揭露真相。"},{"source_id":2678,"word":"underscore","meaning":"強調","example":"The broken helmet helped underscore the importance of wearing protective gear.","example_zh":"破損的安全帽突顯佩戴護具的重要性。","original_meaning":"強調","original_example":"Underscore the importance.","original_example_zh":"強調其重要性。"},{"source_id":2679,"word":"uphold","meaning":"維護","example":"The referee worked to uphold fair play throughout the match.","example_zh":"裁判在整場比賽中努力維護公平競賽。","original_meaning":"維護","original_example":"Uphold the law.","original_example_zh":"恪守法律。"},{"source_id":2680,"word":"utmost","meaning":"最大的","example":"The students handled the ancient bowl with the utmost care.","example_zh":"學生極其小心地拿取古老陶碗。","original_meaning":"最大的","original_example":"Of utmost importance.","original_example_zh":"至關重要。"},{"source_id":2681,"word":"vague","meaning":"模糊的","example":"The vague directions left us unsure which trail to follow.","example_zh":"模糊的指示讓我們不確定該走哪條步道。","original_meaning":"模糊的","original_example":"A vague memory.","original_example_zh":"模糊的記憶。"},{"source_id":2682,"word":"vanish","meaning":"消失","example":"The rabbit seemed to vanish behind the thick bushes.","example_zh":"兔子彷彿消失在濃密灌木後方。","original_meaning":"消失","original_example":"The ship vanished.","original_example_zh":"船隻消失無蹤。"},{"source_id":2683,"word":"venture","meaning":"冒險事業","example":"Opening a small repair shop was the family's first business venture.","example_zh":"開一間小修理店，是這個家庭第一次創業嘗試。","original_meaning":"冒險事業","original_example":"A business venture.","original_example_zh":"一項商業投資。"},{"source_id":2684,"word":"verdict","meaning":"判決","example":"The jury returned to the courtroom to announce its verdict.","example_zh":"陪審團回到法庭，宣布裁決。","original_meaning":"判決","original_example":"A guilty verdict.","original_example_zh":"一項有罪判決。"},{"source_id":2685,"word":"versatile","meaning":"多才多藝的","example":"The versatile musician could play the violin, piano, and flute.","example_zh":"這位多才多藝的音樂家會拉小提琴、彈鋼琴和吹長笛。","original_meaning":"多才多藝的","original_example":"A versatile player.","original_example_zh":"一位多才多藝的球員。"},{"source_id":2686,"word":"viable","meaning":"可行的","example":"The rooftop garden is viable because the building can safely support the planters.","example_zh":"建築能安全承受種植箱，所以屋頂花園計畫可行。","original_meaning":"可行的","original_example":"A viable option.","original_example_zh":"一個可行的選項。"},{"source_id":2687,"word":"vigorous","meaning":"有活力的","example":"The team began the day with vigorous exercise on the sports field.","example_zh":"小組以充滿活力的操場運動開始一天。","original_meaning":"有活力的","original_example":"Vigorous exercise.","original_example_zh":"劇烈的運動。"},{"source_id":2688,"word":"volatile","meaning":"不穩定的","example":"The volatile weather changed from sunshine to hail within an hour.","example_zh":"天氣很不穩定，一小時內就從晴天變成下冰雹。","original_meaning":"不穩定的","original_example":"A volatile market.","original_example_zh":"波動的市場。"},{"source_id":2689,"word":"warrant","meaning":"保證；使有必要","example":"The deep crack was serious enough to warrant closing the bridge.","example_zh":"深深的裂縫相當嚴重，有必要封閉橋梁。","original_meaning":"保證","original_example":"The situation warrants action.","original_example_zh":"情勢需要採取行動。"},{"source_id":2690,"word":"wield","meaning":"揮舞；運用","example":"The sculptor learned to wield the chisel with care and precision.","example_zh":"雕刻師學會小心而精準地運用鑿刀。","original_meaning":"揮舞","original_example":"Wield power.","original_example_zh":"掌握權力。"},{"source_id":2691,"word":"zeal","meaning":"熱忱","example":"The volunteers worked with zeal to restore the neglected garden.","example_zh":"志工滿懷熱忱地修復荒廢花園。","original_meaning":"熱忱","original_example":"Work with zeal.","original_example_zh":"熱忱地工作。"},{"source_id":3078,"word":"aboriginal","meaning":"原住民的","example":"The museum displayed aboriginal baskets made by local Indigenous artists.","example_zh":"博物館展示當地原住民族藝術家製作的籃子。","original_meaning":"原住民的","original_example":"The aboriginal people have lived on this land for thousands of years.","original_example_zh":"原住民在這片土地上生活了數千年。"},{"source_id":3079,"word":"abstain","meaning":"棄權","example":"One member chose to abstain from voting because she needed more information.","example_zh":"一位成員因為還需要更多資訊，選擇投票時棄權。","original_meaning":"棄權","original_example":"He decided to abstain from voting due to a conflict of interest.","original_example_zh":"他因利益衝突而決定投棄權票。"},{"source_id":3080,"word":"accessibility","meaning":"可及性","example":"The new ramp improved accessibility for visitors using wheelchairs.","example_zh":"新坡道提升使用輪椅訪客的通行便利性。","original_meaning":"可及性","original_example":"The new design improves accessibility for people with disabilities.","original_example_zh":"新設計改善了身心障礙者的無障礙使用。"},{"source_id":3081,"word":"accountability","meaning":"問責","example":"The council showed accountability by explaining how every donation was spent.","example_zh":"委員會說明每筆捐款的用途，展現負責透明的態度。","original_meaning":"問責","original_example":"The manager emphasized accountability within the team.","original_example_zh":"經理強調團隊內的問責制。"},{"source_id":3082,"word":"accreditation","meaning":"認證","example":"The school earned accreditation after a careful review of its courses.","example_zh":"學校的課程經仔細審查後獲得認證。","original_meaning":"認證","original_example":"The university received official accreditation last year.","original_example_zh":"該大學去年獲得官方認證。"},{"source_id":3083,"word":"acumen","meaning":"敏銳","example":"Her business acumen helped the small craft stall attract regular customers.","example_zh":"她敏銳的商業判斷，幫助手作小攤吸引固定顧客。","original_meaning":"敏銳","original_example":"Her business acumen helped the company grow rapidly.","original_example_zh":"她的商業頭腦幫助公司迅速成長。"},{"source_id":3084,"word":"addictive","meaning":"上癮的","example":"The addictive game made it difficult for Tom to put his phone away.","example_zh":"那款讓人著迷的遊戲使湯姆很難放下手機。","original_meaning":"上癮的","original_example":"Many people find social media highly addictive.","original_example_zh":"許多人覺得社群媒體極具成癮性。"},{"source_id":3085,"word":"adhesive","meaning":"黏性的","example":"The adhesive tape held the torn paper model together.","example_zh":"膠帶把撕裂的紙模型黏在一起。","original_meaning":"黏性的","original_example":"This glue is strong and highly adhesive.","original_example_zh":"這種膠水強度高且黏性極佳。"},{"source_id":3086,"word":"adolescence","meaning":"青春期","example":"During adolescence, Leo learned to balance schoolwork with new responsibilities.","example_zh":"青春期時，里歐學著平衡課業與新的責任。","original_meaning":"青春期","original_example":"Adolescence is a critical stage of personal development.","original_example_zh":"青春期是個人發展的重要階段。"},{"source_id":3087,"word":"adversary","meaning":"對手","example":"Even after the match, the chess player treated her adversary with respect.","example_zh":"即使比賽結束，棋手仍尊重自己的對手。","original_meaning":"對手","original_example":"He saw his rival as a worthy adversary.","original_example_zh":"他視對手為值得尊敬的對手。"},{"source_id":3088,"word":"affirmative","meaning":"肯定的","example":"The coach gave an affirmative nod when we asked to begin practice.","example_zh":"我們詢問能否開始練習時，教練肯定地點了點頭。","original_meaning":"肯定的","original_example":"She gave an affirmative answer to the question.","original_example_zh":"她對這個問題給出了肯定的回答。"},{"source_id":3089,"word":"affluent","meaning":"富裕的","example":"The affluent family donated new instruments to the community music room.","example_zh":"富裕的家庭捐贈新樂器給社區音樂教室。","original_meaning":"富裕的","original_example":"They live in an affluent neighborhood.","original_example_zh":"他們住在一個富裕的社區。"},{"source_id":3090,"word":"aggression","meaning":"侵略；攻擊行為","example":"The referee stopped the game when the player's aggression became unsafe.","example_zh":"球員的攻擊行為變得危險時，裁判停止了比賽。","original_meaning":"侵略","original_example":"The conflict escalated due to increasing aggression.","original_example_zh":"由於侵略性日益增強，衝突升級了。"},{"source_id":3091,"word":"agile","meaning":"敏捷的","example":"The agile cat jumped neatly from the wall onto a narrow ledge.","example_zh":"敏捷的貓俐落地從牆上跳到狹窄的平台。","original_meaning":"敏捷的","original_example":"The athlete remained agile despite his age.","original_example_zh":"儘管年事已高，這位運動員依然身手敏捷。"},{"source_id":3092,"word":"ailment","meaning":"疾病","example":"The nurse asked about the minor ailment that had kept him home.","example_zh":"護理師詢問是什麼小毛病讓他留在家裡休息。","original_meaning":"疾病","original_example":"He visited the doctor for a minor ailment.","original_example_zh":"他因輕微不適去看醫生。"},{"source_id":3093,"word":"allegory","meaning":"寓言","example":"The story of animals sharing a well is an allegory about cooperation.","example_zh":"動物共用水井的故事，是一則談合作的寓言。","original_meaning":"寓言","original_example":"The story is an allegory of human nature.","original_example_zh":"這個故事是對人性的一則寓言。"},{"source_id":3094,"word":"alleviation","meaning":"減輕","example":"The shade brought welcome alleviation of the afternoon heat.","example_zh":"樹蔭讓午後的暑熱獲得舒緩。","original_meaning":"減輕","original_example":"The medicine brought relief and alleviation of pain.","original_example_zh":"這藥帶來了舒緩與疼痛的減輕。"},{"source_id":3095,"word":"allot","meaning":"分配","example":"The teacher will allot each group a small plot in the school garden.","example_zh":"老師會分配一小塊校園菜園給每組學生。","original_meaning":"分配","original_example":"The manager will allot tasks to each team member.","original_example_zh":"經理會將任務分配給每位團隊成員。"},{"source_id":3096,"word":"amalgamate","meaning":"合併","example":"The two small clubs decided to amalgamate into one larger team.","example_zh":"兩個小社團決定合併成一個較大的團隊。","original_meaning":"合併","original_example":"The two companies decided to amalgamate.","original_example_zh":"兩家公司決定合併。"},{"source_id":3097,"word":"ambivalent","meaning":"矛盾的","example":"Mina felt ambivalent about moving because she would miss her friends.","example_zh":"米娜對搬家心情矛盾，因為她會想念朋友。","original_meaning":"矛盾的","original_example":"She felt ambivalent about the decision.","original_example_zh":"她對這個決定感到矛盾。"},{"source_id":3098,"word":"amenity","meaning":"設施","example":"The campsite's most useful amenity was its clean drinking-water station.","example_zh":"營地最實用的設施是乾淨的飲水補給站。","original_meaning":"設施","original_example":"The hotel offers many modern amenities.","original_example_zh":"這家飯店提供許多現代化的設施。"},{"source_id":3099,"word":"amnesia","meaning":"失憶","example":"The patient with amnesia used family photographs to help rebuild her memories.","example_zh":"有失憶症的病人透過家人照片，幫助重建記憶。","original_meaning":"失憶","original_example":"The patient suffered from temporary amnesia.","original_example_zh":"病患患有暫時性失憶症。"},{"source_id":3100,"word":"amplify","meaning":"放大","example":"The microphone helped amplify the speaker's quiet voice.","example_zh":"麥克風幫助放大演講者輕柔的聲音。","original_meaning":"放大","original_example":"The device can amplify sound signals.","original_example_zh":"該裝置能放大聲音訊號。"},{"source_id":3101,"word":"analogue","meaning":"類似物","example":"The small water wheel served as an analogue of the larger machine.","example_zh":"小水輪作為大型機械的類似模型。","original_meaning":"類似物","original_example":"This model is an analogue of the real system.","original_example_zh":"此模型是真實系統的類比。"},{"source_id":3102,"word":"anatomy","meaning":"解剖學","example":"The students studied anatomy using a model of the human skeleton.","example_zh":"學生使用人體骨骼模型學習解剖學。","original_meaning":"解剖學","original_example":"She studied human anatomy in college.","original_example_zh":"她在大學主修人體解剖學。"},{"source_id":3103,"word":"anecdote","meaning":"軼事","example":"Grandfather told an amusing anecdote about his first train journey.","example_zh":"祖父講了一段他第一次搭火車的有趣軼事。","original_meaning":"軼事","original_example":"He shared an amusing anecdote during the speech.","original_example_zh":"他在演講中分享了一個有趣的軼事。"},{"source_id":3104,"word":"anguish","meaning":"痛苦","example":"The owner felt anguish when her beloved dog went missing.","example_zh":"心愛的狗走失時，飼主感到極度痛苦。","original_meaning":"痛苦","original_example":"She cried out in anguish after hearing the news.","original_example_zh":"聽到這個消息後，她痛苦地哭喊起來。"},{"source_id":3105,"word":"animate","meaning":"使有生氣；製作動畫","example":"The art club used stop-motion pictures to animate a tiny clay bird.","example_zh":"美術社用定格照片，讓小陶鳥在動畫中動起來。","original_meaning":"使有生氣","original_example":"The film was animated to entertain children.","original_example_zh":"這部電影是為了娛樂兒童而製作的動畫。"},{"source_id":3106,"word":"annihilate","meaning":"殲滅；徹底摧毀","example":"A powerful wave can annihilate a sandcastle in seconds.","example_zh":"強大的海浪能在幾秒內徹底摧毀沙堡。","original_meaning":"殲滅","original_example":"The army aimed to annihilate the enemy forces.","original_example_zh":"軍隊旨在殲滅敵軍。"},{"source_id":3107,"word":"annotate","meaning":"註解","example":"The students began to annotate the diagram with their observations.","example_zh":"學生開始在圖表旁註記觀察結果。","original_meaning":"註解","original_example":"Students are asked to annotate the text carefully.","original_example_zh":"學生們被要求仔細為文本添加註解。"},{"source_id":3108,"word":"anomaly","meaning":"異常","example":"One unusually pale leaf was an anomaly among the healthy green leaves.","example_zh":"健康綠葉之中，一片異常蒼白的葉子格外不同。","original_meaning":"異常","original_example":"The scientist detected an anomaly in the data.","original_example_zh":"科學家在數據中發現了異常。"},{"source_id":3109,"word":"anthem","meaning":"國歌","example":"The school choir rehearsed the anthem before the ceremony.","example_zh":"學校合唱團在典禮前排練國歌。","original_meaning":"國歌","original_example":"They sang the national anthem proudly.","original_example_zh":"他們自豪地唱起了國歌。"},{"source_id":3110,"word":"anthropology","meaning":"人類學","example":"The anthropology exhibit explored how families lived in different societies.","example_zh":"人類學展覽探討不同社會的家庭如何生活。","original_meaning":"人類學","original_example":"Anthropology studies human societies and cultures.","original_example_zh":"人類學研究人類社會與文化。"},{"source_id":3111,"word":"antibody","meaning":"抗體","example":"The model showed an antibody attaching to a matching part of a germ.","example_zh":"模型展示抗體如何附著在病菌相對應的部位。","original_meaning":"抗體","original_example":"The body produces antibodies to fight infections.","original_example_zh":"人體會產生抗體來對抗感染。"},{"source_id":3112,"word":"antiquity","meaning":"古代","example":"The clay lamp from antiquity was displayed in a protective glass case.","example_zh":"這盞古代陶燈展示在保護玻璃櫃內。","original_meaning":"古代","original_example":"Ancient artifacts date back to antiquity.","original_example_zh":"古代文物可追溯至遠古時期。"},{"source_id":3113,"word":"apathy","meaning":"冷漠","example":"The teacher tried to replace the class's apathy with curiosity about science.","example_zh":"老師試著用科學好奇心取代全班的冷漠。","original_meaning":"冷漠","original_example":"His apathy toward work affected his performance.","original_example_zh":"他對工作的冷漠影響了他的表現。"},{"source_id":3114,"word":"apocalypse","meaning":"末日","example":"The novel imagined an apocalypse that left the great city silent.","example_zh":"小說想像一場讓大城市陷入寂靜的末日災難。","original_meaning":"末日","original_example":"The movie depicts a post-apocalyptic world.","original_example_zh":"這部電影描繪了一個末日後的世界。"},{"source_id":3115,"word":"appalling","meaning":"駭人的","example":"The appalling amount of rubbish on the beach shocked the volunteers.","example_zh":"海灘上垃圾多得駭人，令志工震驚。","original_meaning":"駭人的","original_example":"The conditions in the factory were appalling.","original_example_zh":"工廠內的狀況令人髮指。"},{"source_id":3116,"word":"appease","meaning":"安撫","example":"The guide used a calm voice to appease the worried visitors.","example_zh":"導覽員用平靜的聲音安撫擔心的遊客。","original_meaning":"安撫","original_example":"They tried to appease the angry customer.","original_example_zh":"他們試圖安撫那位生氣的顧客。"},{"source_id":3117,"word":"appraisal","meaning":"評估","example":"The restorer made an appraisal of the painting's condition before cleaning it.","example_zh":"修復師清潔畫作前，先評估它的保存狀況。","original_meaning":"評估","original_example":"The company conducted a performance appraisal.","original_example_zh":"公司進行了績效評估。"},{"source_id":3118,"word":"apprehensive","meaning":"憂慮的","example":"Nora felt apprehensive before stepping onto the stage for her first solo.","example_zh":"第一次獨奏上台前，諾拉感到忐忑。","original_meaning":"憂慮的","original_example":"She felt apprehensive about the interview.","original_example_zh":"她對面試感到忐忑不安。"},{"source_id":3119,"word":"apprentice","meaning":"學徒","example":"The apprentice watched the carpenter carefully before trying the tool.","example_zh":"學徒在試用工具前，仔細觀察木匠的動作。","original_meaning":"學徒","original_example":"The apprentice learned skills from his mentor.","original_example_zh":"學徒從導師那裡學到了技能。"},{"source_id":3120,"word":"aquatic","meaning":"水生的","example":"The pond supports many aquatic plants and animals.","example_zh":"這座池塘養育許多水生植物與動物。","original_meaning":"水生的","original_example":"Aquatic plants grow in water environments.","original_example_zh":"水生植物生長於水生環境中。"},{"source_id":3121,"word":"archive","meaning":"檔案","example":"The old photographs were stored in the town's historical archive.","example_zh":"老照片保存在城鎮的歷史檔案庫裡。","original_meaning":"檔案","original_example":"The documents are stored in an archive.","original_example_zh":"文件存儲於檔案庫中。"},{"source_id":3122,"word":"arduous","meaning":"艱難的","example":"Carrying the supplies up the long hill was an arduous task.","example_zh":"把物資搬上長長山坡，是項艱難工作。","original_meaning":"艱難的","original_example":"Climbing the mountain was an arduous task.","original_example_zh":"攀登這座山是一項艱鉅的任務。"},{"source_id":3123,"word":"aristocrat","meaning":"貴族","example":"The portrait showed an aristocrat in an elegant eighteenth-century coat.","example_zh":"畫像裡是一位穿著優雅十八世紀外套的貴族。","original_meaning":"貴族","original_example":"The aristocrat lived in a grand mansion.","original_example_zh":"那位貴族住在宏偉的宅邸裡。"},{"source_id":3124,"word":"armament","meaning":"武器；軍備","example":"The museum's armament collection included old shields and suits of armor.","example_zh":"博物館的軍備收藏包含古盾牌與盔甲。","original_meaning":"武器","original_example":"The country increased its military armament.","original_example_zh":"該國加強了軍事武裝。"},{"source_id":3125,"word":"array","meaning":"一系列","example":"The market offered an array of colorful fruits from nearby farms.","example_zh":"市場供應各式各樣來自附近農場的繽紛水果。","original_meaning":"一系列","original_example":"The exhibition displayed an array of artworks.","original_example_zh":"展覽中陳列了各式各樣的藝術作品。"},{"source_id":3126,"word":"arson","meaning":"縱火","example":"Investigators found evidence of arson after the empty warehouse fire.","example_zh":"空倉庫火災後，調查員發現縱火證據。","original_meaning":"縱火","original_example":"Arson is considered a serious crime.","original_example_zh":"縱火被視為嚴重罪行。"},{"source_id":3127,"word":"artifact","meaning":"文物","example":"The archaeologist carefully lifted the small artifact from the soil.","example_zh":"考古學家小心從泥土中取出小文物。","original_meaning":"文物","original_example":"The museum houses ancient artifacts.","original_example_zh":"博物館內收藏著古代文物。"},{"source_id":3128,"word":"ascertain","meaning":"確定","example":"We tested the water to ascertain whether it was clean enough for the plants.","example_zh":"我們檢測水質，確認水是否乾淨到適合澆灌植物。","original_meaning":"確定","original_example":"We need to ascertain the facts before deciding.","original_example_zh":"我們必須在決策前查明事實。"},{"source_id":3129,"word":"assertion","meaning":"斷言","example":"The students tested the assertion that the new bridge model was stronger.","example_zh":"學生測試新橋梁模型比較堅固的說法。","original_meaning":"斷言","original_example":"His assertion was supported by evidence.","original_example_zh":"他的說法有證據支持。"},{"source_id":3130,"word":"assimilate","meaning":"同化；吸收","example":"It takes time to assimilate new knowledge after a difficult lesson.","example_zh":"上完困難的課程後，需要時間吸收新知。","original_meaning":"同化","original_example":"Immigrants gradually assimilate into society.","original_example_zh":"移民逐漸融入社會。"},{"source_id":3131,"word":"asylum","meaning":"庇護","example":"The family found asylum in a country where they could live safely.","example_zh":"這個家庭在能讓他們安全生活的國家獲得庇護。","original_meaning":"庇護","original_example":"The refugee sought asylum in another country.","original_example_zh":"難民在另一個國家尋求庇護。"},{"source_id":3132,"word":"atrocity","meaning":"暴行","example":"The museum reminds visitors of the atrocity committed against civilians during the war.","example_zh":"博物館提醒訪客，戰爭中曾發生針對平民的暴行。","original_meaning":"暴行","original_example":"The war resulted in terrible atrocities.","original_example_zh":"戰爭導致了可怕的暴行。"},{"source_id":3133,"word":"attire","meaning":"服裝","example":"The orchestra members wore formal attire for the evening concert.","example_zh":"管弦樂團成員穿著正式服裝參加晚間音樂會。","original_meaning":"服裝","original_example":"Formal attire is required for the event.","original_example_zh":"活動要求穿著正式服裝。"},{"source_id":3134,"word":"audit","meaning":"審計","example":"The treasurer prepared all the receipts for the club's annual audit.","example_zh":"財務幹部備妥所有收據，準備社團年度審計。","original_meaning":"審計","original_example":"The company underwent a financial audit.","original_example_zh":"該公司接受了財務審計。"},{"source_id":3135,"word":"augment","meaning":"增加","example":"The volunteers used donated books to augment the village library's collection.","example_zh":"志工用捐贈書籍增加村落圖書館的藏書。","original_meaning":"增加","original_example":"Exercise can augment your strength.","original_example_zh":"運動可以增強你的力量。"},{"source_id":3136,"word":"auspicious","meaning":"吉祥的","example":"The clear sky was an auspicious start to the outdoor festival.","example_zh":"晴朗天空為戶外節慶帶來吉祥順利的開端。","original_meaning":"吉祥的","original_example":"It was an auspicious beginning to the project.","original_example_zh":"這是該專案一個吉利的開端。"},{"source_id":3137,"word":"austerity","meaning":"緊縮","example":"During austerity, the club repaired old equipment instead of buying new items.","example_zh":"經費緊縮期間，社團修理舊設備，沒有購買新品。","original_meaning":"緊縮","original_example":"The government implemented austerity measures.","original_example_zh":"政府實施了緊縮措施。"},{"source_id":3138,"word":"autonomy","meaning":"自治；自主","example":"The teacher gave each group autonomy to choose its own science project.","example_zh":"老師讓每組自主選擇自己的科學專題。","original_meaning":"自治","original_example":"The region gained political autonomy.","original_example_zh":"該地區獲得了政治自治權。"},{"source_id":3139,"word":"avail","meaning":"有益；利用","example":"The students can avail themselves of the library's free workshops.","example_zh":"學生可以利用圖書館提供的免費工作坊。","original_meaning":"有益","original_example":"His efforts will avail him nothing.","original_example_zh":"他的努力將徒勞無功。"},{"source_id":3140,"word":"avalanche","meaning":"雪崩","example":"The guide pointed out the distant avalanche from a safe lookout.","example_zh":"嚮導從安全觀景點指出遠方的雪崩。","original_meaning":"雪崩","original_example":"The avalanche destroyed several houses.","original_example_zh":"雪崩摧毀了數棟房屋。"},{"source_id":3141,"word":"aversion","meaning":"厭惡","example":"His aversion to loud noise made the quiet library his favorite place.","example_zh":"他厭惡吵雜聲，因此安靜的圖書館成了他最喜歡的地方。","original_meaning":"厭惡","original_example":"She has a strong aversion to spicy food.","original_example_zh":"她非常討厭辛辣食物。"},{"source_id":3142,"word":"axis","meaning":"軸","example":"The globe spins around a tilted axis.","example_zh":"地球儀繞著傾斜的軸轉動。","original_meaning":"軸","original_example":"The Earth rotates on its axis.","original_example_zh":"地球繞其軸心自轉。"},{"source_id":3143,"word":"bail","meaning":"保釋","example":"The court granted bail while the accused person waited for the trial.","example_zh":"法院准予保釋，讓被告在外等候審判。","original_meaning":"保釋","original_example":"The suspect was released on bail.","original_example_zh":"該名嫌疑人已獲保釋。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-stringent-01-v1","level":"senior","word":"stringent","sort_order":1,"sense":"嚴格的","alt_zh":"老師仔細檢查高中生的護目鏡與手套，才讓他們操作實驗器材。","example":"The laboratory has stringent rules for handling fragile equipment.","example_zh":"實驗室對操作精密易碎設備有嚴格規定。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/stringent-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-subsidize-01-v1","level":"senior","word":"subsidize","sort_order":1,"sense":"補助","alt_zh":"高中生在公車站上車，公所人員向司機交付補助文件，場景溫暖。","example":"The town will subsidize bus rides so more students can travel to school.","example_zh":"鎮公所將補助公車車資，讓更多學生方便上學。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/subsidize-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-suffice-01-v1","level":"senior","word":"suffice","sort_order":1,"sense":"足夠","alt_zh":"高中生用一大壺水從容澆完幾個小花圃，壺裡還有少量水。","example":"One large watering can should suffice for these small flower beds.","example_zh":"一個大澆水壺應該足夠澆灌這些小花圃。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/suffice-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-superficial-01-v1","level":"senior","word":"superficial","sort_order":1,"sense":"膚淺的；表面的","alt_zh":"高中生匆匆看過模型橋表面，老師把模型輕抬，指出底下隱藏的裂縫。","example":"A superficial glance at the model failed to reveal the crack underneath.","example_zh":"只粗略看一下模型，沒能發現底下的裂縫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/superficial-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-suppress-01-v1","level":"senior","word":"suppress","sort_order":1,"sense":"壓制","alt_zh":"高中女生在劇場排練時掩著嘴忍笑，其他同學認真排練。","example":"Mei tried to suppress a laugh during the serious rehearsal.","example_zh":"嚴肅排練時，美努力忍住笑。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/suppress-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-surge-01-v1","level":"senior","word":"surge","sort_order":1,"sense":"激增","alt_zh":"博物館入口人潮一下子增加，工作人員引導遊客有序進入。","example":"A surge of visitors arrived when the museum opened its new exhibition.","example_zh":"博物館新展覽開幕時，大批參觀者湧入。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/surge-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-surplus-01-v1","level":"senior","word":"surplus","sort_order":1,"sense":"過剩","alt_zh":"高中生留下自用蔬菜後，把多出的幾籃新鮮蔬菜交給收容所志工。","example":"We donated the surplus vegetables from our school garden to a local shelter.","example_zh":"我們把校園菜園多收成的蔬菜捐給當地收容所。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/surplus-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-surveillance-01-v1","level":"senior","word":"surveillance","sort_order":1,"sense":"監視","alt_zh":"博物館牆角有監視攝影機，管理員在螢幕上查看無字展廳影像。","example":"The museum uses surveillance cameras to help protect its valuable paintings.","example_zh":"博物館使用監視攝影機協助保護珍貴畫作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/surveillance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-susceptible-01-v1","level":"senior","word":"susceptible","sort_order":1,"sense":"易受影響的","alt_zh":"高中生替柔弱幼苗架設防風網，附近風吹得葉片彎曲。","example":"Young seedlings are susceptible to damage from strong winds.","example_zh":"幼苗容易受到強風吹襲而受損。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/susceptible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-swift-01-v1","level":"senior","word":"swift","sort_order":1,"sense":"迅速的","alt_zh":"成年救生員迅速遞出救援浮具，協助泳客在安全泳池靠岸。","example":"The lifeguard's swift response helped the tired swimmer reach the pool edge.","example_zh":"救生員迅速的反應，幫助疲憊泳客到達池邊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/swift-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tangible-01-v1","level":"senior","word":"tangible","sort_order":1,"sense":"有形的","alt_zh":"高中生自豪地雙手捧著完成的木製鳥屋，桌上還有工具。","example":"The finished birdhouse was tangible proof of the students' hard work.","example_zh":"完成的鳥屋是學生努力的具體成果。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tangible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tariff-01-v1","level":"senior","word":"tariff","sort_order":1,"sense":"關稅","alt_zh":"港口海關人員查看進口腳踏車貨箱，進口商把額外硬幣放進繳費盤。","example":"The tariff increased the cost of imported bicycles.","example_zh":"關稅提高了進口腳踏車的成本。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tariff-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tedious-01-v1","level":"senior","word":"tedious","sort_order":1,"sense":"冗長的","alt_zh":"高中生耐心把大量小珠子依顏色分進盒子，有人略顯疲憊。","example":"Sorting hundreds of tiny beads was tedious, but the team finished together.","example_zh":"分類數百顆小珠子很費工又乏味，但小組合作完成了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tedious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-terrain-01-v1","level":"senior","word":"terrain","sort_order":1,"sense":"地形","alt_zh":"高中健行隊在嚮導帶領下小心走過崎嶇多石的山徑。","example":"The rocky terrain made us walk slowly and carefully.","example_zh":"岩石遍布的地形讓我們走得緩慢又小心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/terrain-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-threshold-01-v1","level":"senior","word":"threshold","sort_order":1,"sense":"門檻","alt_zh":"小狗站在溫暖家門的低門檻前，家人在屋內友善迎接。","example":"The puppy paused at the threshold before entering its new home.","example_zh":"小狗走進新家前，在門檻前停了一下。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/threshold-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tolerate-01-v1","level":"senior","word":"tolerate","sort_order":1,"sense":"容忍","alt_zh":"高中生在薄霜覆蓋的山間花園查看仍健康挺立的耐寒植物。","example":"These hardy plants can tolerate cold nights in the mountain garden.","example_zh":"這些耐寒植物能忍受山間花園寒冷的夜晚。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tolerate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trajectory-01-v1","level":"senior","word":"trajectory","sort_order":1,"sense":"軌道；軌跡","alt_zh":"高中生在操場拋球，幾個淡淡位置標記連成單一弧線顯示球的飛行路徑。","example":"The students traced the trajectory of the ball as it curved through the air.","example_zh":"學生觀察球在空中拋出弧線的運動軌跡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trajectory-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-traverse-01-v1","level":"senior","word":"traverse","sort_order":1,"sense":"穿越","alt_zh":"嚮導帶高中健行隊沿安全步道穿過寬闊山谷，遠處可見營地。","example":"The hikers will traverse the valley before reaching the campsite.","example_zh":"健行者將穿越山谷，再到達營地。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/traverse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-turbulent-01-v1","level":"senior","word":"turbulent","sort_order":1,"sense":"動盪的；湍急的","alt_zh":"高中生從安全高處望向翻湧、有白色浪花的河流。","example":"The river became turbulent after days of heavy rain.","example_zh":"連日豪雨後，河水變得湍急。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/turbulent-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-uncover-01-v1","level":"senior","word":"uncover","sort_order":1,"sense":"揭露；發掘","alt_zh":"考古老師指導高中生用軟毛刷輕刷泥土，逐漸露出陶罐。","example":"The students used soft brushes to uncover a buried clay pot.","example_zh":"學生用軟毛刷清理出埋在土裡的陶罐。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/uncover-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-underscore-01-v1","level":"senior","word":"underscore","sort_order":1,"sense":"強調","alt_zh":"老師向高中生展示受撞後外殼受損的安全帽，提醒大家戴好護具。","example":"The broken helmet helped underscore the importance of wearing protective gear.","example_zh":"破損的安全帽突顯佩戴護具的重要性。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/underscore-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-uphold-01-v1","level":"senior","word":"uphold","sort_order":1,"sense":"維護","alt_zh":"裁判公平地介入籃球比賽，讓兩隊高中球員遵守規則。","example":"The referee worked to uphold fair play throughout the match.","example_zh":"裁判在整場比賽中努力維護公平競賽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/uphold-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-utmost-01-v1","level":"senior","word":"utmost","sort_order":1,"sense":"最大的","alt_zh":"高中生戴手套，謹慎用雙手托住古老陶碗，老師在旁看護。","example":"The students handled the ancient bowl with the utmost care.","example_zh":"學生極其小心地拿取古老陶碗。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/utmost-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vague-01-v1","level":"senior","word":"vague","sort_order":1,"sense":"模糊的","alt_zh":"高中生在步道岔路查看只有模糊路線的舊地圖，神情困惑。","example":"The vague directions left us unsure which trail to follow.","example_zh":"模糊的指示讓我們不確定該走哪條步道。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vague-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vanish-01-v1","level":"senior","word":"vanish","sort_order":1,"sense":"消失","alt_zh":"高中生望著灌木，兔子的最後一點尾巴正消失在枝葉間。","example":"The rabbit seemed to vanish behind the thick bushes.","example_zh":"兔子彷彿消失在濃密灌木後方。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vanish-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-venture-01-v1","level":"senior","word":"venture","sort_order":1,"sense":"冒險事業","alt_zh":"家人與高中孩子一起打開新修理店的門，整齊擺好工具迎接首位客人。","example":"Opening a small repair shop was the family's first business venture.","example_zh":"開一間小修理店，是這個家庭第一次創業嘗試。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/venture-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-verdict-01-v1","level":"senior","word":"verdict","sort_order":1,"sense":"判決","alt_zh":"莊嚴法庭中，陪審團代表起身向法官提交裁決文件。","example":"The jury returned to the courtroom to announce its verdict.","example_zh":"陪審團回到法庭，宣布裁決。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/verdict-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-versatile-01-v1","level":"senior","word":"versatile","sort_order":1,"sense":"多才多藝的","alt_zh":"高中音樂家坐在鋼琴旁，手持提琴，桌上有長笛，準備不同樂器演出。","example":"The versatile musician could play the violin, piano, and flute.","example_zh":"這位多才多藝的音樂家會拉小提琴、彈鋼琴和吹長笛。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/versatile-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-viable-01-v1","level":"senior","word":"viable","sort_order":1,"sense":"可行的","alt_zh":"老師與高中生在安全屋頂，查看輕型種植箱與已健康生長的蔬菜。","example":"The rooftop garden is viable because the building can safely support the planters.","example_zh":"建築能安全承受種植箱，所以屋頂花園計畫可行。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/viable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vigorous-01-v1","level":"senior","word":"vigorous","sort_order":1,"sense":"有活力的","alt_zh":"高中生在晨光操場精神飽滿地跑步與伸展。","example":"The team began the day with vigorous exercise on the sports field.","example_zh":"小組以充滿活力的操場運動開始一天。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vigorous-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-volatile-01-v1","level":"senior","word":"volatile","sort_order":1,"sense":"不穩定的","alt_zh":"高中生在堅固室內窗邊驚訝看著小冰雹落下，遠處天空仍有陽光。","example":"The volatile weather changed from sunshine to hail within an hour.","example_zh":"天氣很不穩定，一小時內就從晴天變成下冰雹。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/volatile-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-warrant-01-v1","level":"senior","word":"warrant","sort_order":1,"sense":"保證；使有必要","alt_zh":"工程師指著橋面深裂縫，管理員在安全入口放上封鎖護欄。","example":"The deep crack was serious enough to warrant closing the bridge.","example_zh":"深深的裂縫相當嚴重，有必要封閉橋梁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/warrant-01-v1.webp","local_path":"","style":"generated-senior-v1","vers